const fs = require('fs');
const path = require('path');

const openapiPath = 'd:/Enforcer/EnforcerAPI Documentation.json';
const outputPath = 'd:/Enforcer/src/api/api-contracts.ts';

const openapi = JSON.parse(fs.readFileSync(openapiPath, 'utf8'));

let output = `/**
 * Enforcer API Contracts
 * This file is automatically generated from the OpenAPI specification.
 * Do not edit this file manually.
 */

`;

// 1. Generate Schemas
const schemas = openapi.components.schemas;

function mapType(schema) {
  if (!schema) return 'any';
  if (schema.$ref) {
    return cleanSchemaName(schema.$ref.split('/').pop());
  }
  if (schema.type === 'array') {
    return `${mapType(schema.items)}[]`;
  }
  if (schema.type === 'string') {
    if (schema.format === 'date-time') return 'string'; // or Date
    return 'string';
  }
  if (schema.type === 'integer' || schema.type === 'number') {
    return 'number';
  }
  if (schema.type === 'boolean') {
    return 'boolean';
  }
  if (schema.type === 'object') {
    if (schema.properties) {
      let obj = '{ ';
      for (const [prop, propSchema] of Object.entries(schema.properties)) {
        const isNullable = propSchema.nullable;
        obj += `${prop}${isNullable ? '?' : ''}: ${mapType(propSchema)}; `;
      }
      obj += '}';
      return obj;
    }
    return 'Record<string, any>';
  }
  return 'any';
}

function cleanSchemaName(name) {
  if (name.includes('`1')) {
    const base = name.split('`1')[0].split('.').pop();
    const inner = name.match(/\[\[(.*?),/);
    if (inner && inner[1]) {
      const innerCleaned = cleanSchemaName(inner[1]);
      return `${base}<${innerCleaned}>`;
    }
    return base;
  }

  const parts = name.split('.');
  let baseName = parts.pop();

  // If name is too generic like 'Request' or 'Response', add preceding part for context
  if ((baseName === 'Request' || baseName === 'Response') && parts.length > 0) {
    const context = parts.pop();
    baseName = context + baseName;
  }

  return baseName;
}

// Group schemas to avoid collisions if we use clean names
const schemaEntries = Object.entries(schemas);

// First pass: generate all interfaces
output += `// ============================================
// Data Schemas
// ============================================

`;

// Map of full names to cleaned names to handle references
const nameMap = {};
schemaEntries.forEach(([fullName, schema]) => {
  const cleanName = cleanSchemaName(fullName);
  nameMap[fullName] = cleanName;
});

output += `export interface PagedResponse<T> {
  items: T[] | null;
  totalCount: number;
  pageNumber: number;
  pageSize: number;
  totalPages: number;
  hasPreviousPage: boolean;
  hasNextPage: boolean;
}

`;

schemaEntries.forEach(([fullName, schema]) => {
  if (fullName.includes('PagedResponse`1')) return;

  const cleanName = cleanSchemaName(fullName);

  if (schema.enum) {
    output += `export enum ${cleanName} {\n`;
    if (schema['x-enumNames']) {
      schema.enum.forEach((val, idx) => {
        output += `  ${schema['x-enumNames'][idx]} = ${val},\n`;
      });
    } else {
      // Default to values if names not available (like in the spec I saw)
      // But wait, RateLimitWindow should be Second, Minute, Hour
      // The JSON has "enum": [0, 1, 2] and no x-enumNames. 
      // I'll manually handle RateLimitWindow for now if it's common.
      if (cleanName === 'RateLimitWindow') {
        output += `  Second = 0,\n  Minute = 1,\n  Hour = 2,\n`;
      } else {
        schema.enum.forEach((val, idx) => {
          output += `  Value${val} = ${val},\n`;
        });
      }
    }
    output += `}\n\n`;
  } else {
    output += `export interface ${cleanName} {\n`;
    if (schema.properties) {
      for (const [prop, propSchema] of Object.entries(schema.properties)) {
        const isNullable = propSchema.nullable;
        const type = mapType(propSchema);
        output += `  ${prop}${isNullable ? '?' : ''}: ${type};\n`;
      }
    }
    output += `}\n\n`;
  }
});

// 2. Generate API Endpoints
output += `// ============================================
// API Endpoints
// ============================================

export const API_ENDPOINTS = {
`;

const paths = openapi.paths;
const groups = {};

for (const [path, methods] of Object.entries(paths)) {
  for (const [method, detail] of Object.entries(methods)) {
    const tag = detail.tags ? detail.tags[0] : 'Common';
    if (!groups[tag]) groups[tag] = [];

    groups[tag].push({
      name: detail.summary || detail.operationId || path.split('/').pop(),
      method: method.toUpperCase(),
      path: path,
      summary: detail.summary,
      parameters: detail.parameters || [],
      requestBody: detail.requestBody,
      responses: detail.responses
    });
  }
}

for (const [tag, endpoints] of Object.entries(groups)) {
  const camelTag = tag.charAt(0).toLowerCase() + tag.slice(1);
  output += `  ${camelTag}: {\n`;
  endpoints.forEach(ep => {
    const epName = ep.name.charAt(0).toLowerCase() + ep.name.slice(1);

    // Path builder function if there are path parameters
    const pathParams = ep.parameters.filter(p => p.in === 'path');
    let pathStr = ep.path;
    if (pathParams.length > 0) {
      const args = pathParams.map(p => `${p.name}: string`).join(', ');
      pathStr = '`' + ep.path.replace(/{/g, '${') + '`';
      output += `    ${epName}: {\n`;
      output += `      path: (${args}) => ${pathStr},\n`;
    } else {
      output += `    ${epName}: {\n`;
      output += `      path: '${ep.path}',\n`;
    }

    output += `      method: '${ep.method}',\n`;

    // Request/Response types (approximate)
    let reqType = 'any';
    if (ep.requestBody && ep.requestBody.content['application/json']) {
      reqType = mapType(ep.requestBody.content['application/json'].schema);
    }
    let resType = 'any';
    if (ep.responses['200'] && ep.responses['200'].content && ep.responses['200'].content['application/json']) {
      resType = mapType(ep.responses['200'].content['application/json'].schema);
    }

    output += `      // Request type: ${reqType}\n`;
    output += `      // Response type: ${resType}\n`;
    output += `    },\n`;
  });
  output += `  },\n`;
}

output += `} as const;

export type ApiEndpoints = typeof API_ENDPOINTS;
`;

fs.writeFileSync(outputPath, output);
console.log('API contracts generated successfully at ' + outputPath);
